/**
 * Normalized shape of the NFL Elo model's site data.
 *
 * Source: site/data/site-data.js in github.com/josh-silverman/nfl-ats-predictor,
 * generated by that repo's scripts/build_site.py after each weekly lock.
 * src/lib/nfl-parse.ts maps the raw snake_case file onto these types.
 */

export interface NflTeam {
  name: string;
  color: string;
}

export interface NflSide {
  team: string;
  rank: number;
  record: string;
  /** Last result, e.g. "W 31-23 @ ATL". */
  last: string;
}

export interface NflGame {
  id: string;
  home: string;
  away: string;
  neutral: boolean;
  kickoff: string;
  dayGroup: string;
  /** Model's home win probability at lock. */
  pHome: number;
  /** De-vigged moneyline home win probability at lock. */
  pVegasHome: number | null;
  favorite: string;
  confidence: string;
  ourLine: string;
  vegasLine: string | null;
  bigGap: boolean;
  homeSide: NflSide;
  awaySide: NflSide;
  /** The inputs behind pHome. edge = homeRating + homeField - awayRating, minus any QB adjustment. */
  why: {
    homeRating: number;
    awayRating: number;
    homeField: number;
    qbPts: number;
    qbTeams: string[];
    edge: number;
  };
  result: {
    homeScore: number;
    awayScore: number;
    winner: string;
    weRight: boolean;
    vegasRight: boolean | null;
  } | null;
  qbOut: { team: string; player: string; reason: string }[];
}

export interface NflWeek {
  week: number;
  /** true when predictions were locked live in git before kickoff; false for backfilled weeks. */
  live: boolean;
  lockText: string | null;
  lockUrl: string | null;
  games: NflGame[];
}

export interface NflRanking {
  rank: number;
  team: string;
  rating: number;
  rankChange: number;
  record: string;
  bye: boolean;
  next: { opp: string; home: boolean; pWin: number } | null;
  odds: { wins: number; losses: number; playoff: number; division: number; topSeed: number };
}

export interface NflData {
  meta: {
    season: number;
    currentWeek: number;
    /** e.g. "Oct 26, 2026 9:52 AM ET" */
    generated: string;
    repo: string;
  };
  teams: Record<string, NflTeam>;
  weeks: NflWeek[];
  rankings: NflRanking[];
  /** team -> [week, rating after that week]; week 0 is preseason. */
  history: Record<string, [number, number][]>;
  /** 2019-2025 walk-forward accuracy (share of winners picked). */
  backtest: { games: number; elo: number; vegas: number; alwaysHome: number };
  /** One worked game from the current season, used to check the Elo math. */
  example: {
    week: number;
    home: string;
    away: string;
    homeRating: number;
    awayRating: number;
    homeField: number;
    gap: number;
    pHome: number;
    homeScore: number;
    awayScore: number;
    homeAfter: number;
    awayAfter: number;
  };
}
